<?php /* Template Name: Login */ if ( is_user_logged_in() ) { wp_safe_redirect( sd_auth_profile_url() ); exit; } get_header(); ?><main id="primary" class="sd-main sd-auth-main"><div class="sd-container sd-content-wrap"><div class="sd-auth-card"><div class="sd-auth-brand"><?php sd_render_site_branding(); ?></div><span class="sd-eyebrow"><?php esc_html_e( 'Welcome back', 'social-discovery' ); ?></span><h1><?php esc_html_e( 'Sign in to Social Discovery', 'social-discovery' ); ?></h1><p class="sd-auth-intro"><?php esc_html_e( 'Pick up where you left off and keep discovering your people.', 'social-discovery' ); ?></p><?php sd_auth_message(); ?><?php if ( function_exists( 'sd_core_login_handler' ) ) : get_template_part( 'template-parts/auth/login-form' ); else : wp_login_form( array( 'remember' => true, 'redirect' => sd_auth_profile_url() ) ); endif; ?><p class="sd-auth-links"><a href="<?php echo esc_url( sd_auth_url( 'forgot-password', wp_lostpassword_url() ) ); ?>"><?php esc_html_e( 'Forgot your password?', 'social-discovery' ); ?></a><?php if ( get_option( 'users_can_register' ) ) : ?> · <a href="<?php echo esc_url( sd_auth_url( 'register', wp_registration_url() ) ); ?>"><?php esc_html_e( 'Create an account', 'social-discovery' ); ?></a><?php endif; ?></p></div></div></main><?php get_footer(); ?>
